 for(int i=0;i<4;++i){auto suffix=String(i+1);p.voiceGain[i]=value(("voiceGain"+suffix).toRawUTF8());p.voicePan[i]=value(("voicePan"+suffix).toRawUTF8());p.voiceFormant[i]=value(("voiceFormant"+suffix).toRawUTF8());}for(int i=0;i<5;++i){auto suffix=String(i+2);p.eqHz[i]=value(("eqHz"+suffix).toRawUTF8());p.eqGain[i]=value(("eqGain"+suffix).toRawUTF8());p.eqQ[i]=value(("eqQ"+suffix).toRawUTF8());}for(int i=0;i<3;++i)p.mbThreshold[i]=value(("mbThreshold"+String(i+1)).toRawUTF8());
#undef V
